{"path": "parser.mjs", "content": "const SKU_RE = /^[A-Z][A-Z0-9-]*$/;
const DIGITS_RE = /^[0-9]+$/;
const MAX = Number.MAX_SAFE_INTEGER;

function parseInteger(raw, field, rowNumber, { positive }) {
  if (!DIGITS_RE.test(raw)) {
    throw new Error(`Row ${rowNumber}: invalid ${field} "${raw}"`);
  }
  const value = Number(raw);
  if (!Number.isSafeInteger(value)) {
    throw new RangeError(`Row ${rowNumber}: ${field} exceeds Number.MAX_SAFE_INTEGER`);
  }
  if (positive && value <= 0) {
    throw new Error(`Row ${rowNumber}: ${field} must be positive`);
  }
  return value;
}

export function parseOrders(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseOrders expects a string');
  }
  const orders = [];
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.trim() === '') continue;
    const rowNumber = i + 1;
    const fields = line.split(',');
    if (fields.length !== 3) {
      throw new Error(`Row ${rowNumber}: expected exactly 3 fields`);
    }
    const sku = fields[0].trim();
    const quantityRaw = fields[1].trim();
    const priceRaw = fields[2].trim();
    if (!SKU_RE.test(sku)) {
      throw new Error(`Row ${rowNumber}: invalid SKU "${sku}"`);
    }
    const quantity = parseInteger(quantityRaw, 'quantity', rowNumber, { positive: true });
    const unitPriceCents = parseInteger(priceRaw, 'unitPriceCents', rowNumber, { positive: false });
    orders.push({ sku, quantity, unitPriceCents });
  }
  return orders;
}
